import{renderModelTheory}from'./model-theory.mjs';
import{unitLabel}from'./unit-notes.mjs';
import{esc,num,download}from'./ui.mjs';
import{parseData,validateRows,splitData,csv,overlapReport}from'./training-data.mjs';
const labels={train:'训练数据',validation:'验证数据',test:'测试数据',input:'计算输入',overall:'整体数据'};
let verification=[],contracts=[],selected='isolation_forest',cache={},endpoint='',token='',connected=false,rerender=()=>{},notice=()=>{},controller=null;
function fresh(){return{slots:{},names:{},ratio:[70,15,15],strategy:null,seed:20261031,epochs:8,result:null,error:'',busy:false,started:0,elapsed:0,operation:'train',history:[]}}
const cur=()=>cache[selected]??(cache[selected]=fresh());const spec=()=>contracts.find(m=>m.id===selected)??contracts[0];
const button=(text,action,extra='')=>`<button class="btn ${extra}" data-studio="${action}">${text}</button>`;
const link=(text,url)=>`<a class="btn small" href="${url}" download>${text}</a>`;
const groupKey=m=>(m.split_policy?.startsWith('group:')?m.split_policy.split(':')[1].split(';')[0]:'well_id');
function policy(m){if(m.id==='rotate')return'coverage';return m.split_policy?.startsWith('group:')?'group':m.split_policy?.includes('time')?'time':'random'}
function diagram(m){const nodes=m.architecture??[];return `<svg class="architecture" viewBox="0 0 380 ${nodes.length*70+12}" role="img" aria-label="${esc(m.name)}模型结构"><defs><marker id="st-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="currentColor"/></marker></defs>${nodes.map((n,i)=>`<g class="arch-node" style="animation-delay:${i*90}ms"><rect x="22" y="${i*70+5}" width="336" height="45" rx="9"/><circle cx="43" cy="${i*70+27}" r="10"/><text x="43" y="${i*70+31}" class="step">${i+1}</text><text x="63" y="${i*70+31}">${esc(n.length>24?n.slice(0,23)+'…':n)}</text><title>${esc(n)}</title>${i<nodes.length-1?`<path class="arch-edge" d="M190 ${i*70+51} V${i*70+73}" marker-end="url(#st-arrow)"/>`:''}</g>`).join('')}</svg>`}
function summaryValue(v){if(v===null||v===undefined)return'—';return typeof v==='object'?JSON.stringify(v):String(v)}
function preview(rows){if(!rows?.length)return '<div class="studio-empty">尚未加载数据</div>';let keys=[...new Set(rows.slice(0,5).flatMap(Object.keys))].slice(0,12);return `<div class="table-scroll"><table><thead><tr>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,4).map(r=>`<tr>${keys.map(k=>`<td title="${esc(summaryValue(r[k]))}">${esc(summaryValue(r[k]).slice(0,72))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function metrics(m,path=''){let out=[];for(const[k,v]of Object.entries(m??{})){if(v&&typeof v==='object'&&!Array.isArray(v))out.push(...metrics(v,path+k+' / '));else if(typeof v==='number')out.push(`<div class="studio-metric"><span>${esc(path+k)}</span><strong>${num(v,Math.abs(v)<1?5:3)}</strong></div>`)}return out}
export function renderStudio(){let m=spec(),s=cur();if(!m)return '<p>模型契约加载中</p>';let strategy=s.strategy??policy(m);let total=['train','validation','test'].reduce((n,k)=>n+(s.slots[k]?.length??0),0),overlap=overlapReport(s.slots,groupKey(m));
 return `<div class="page-head"><div><div class="eyebrow">MODEL OPERATIONS / DATA → TRAIN → EVALUATE</div><h1>模型训练与计算中心</h1><p>上传独立数据，完成可复现训练、验证、测试与结果交付。</p></div><div class="head-controls"><button class="btn" data-route="models">历史基准实验 ↗</button>${link('全部模型数据包','./downloads/model-data/model_data_kit.zip')}</div></div>
 <div class="studio-model-strip">${contracts.map(x=>`<button data-studio-model="${x.id}" class="${selected===x.id?'active':''}"><small>${x.id.toUpperCase().replaceAll('_',' ')}</small><b>${esc(x.name)}</b></button>`).join('')}</div>
 <div class="studio-layout"><div class="studio-main"><section class="panel"><div class="panel-head"><h2>01　${esc(m.name)} · 输入规范</h2><span class="chip amber">${m.kind==='trainable'?'实际训练模型':'规则 / 机理计算'}</span></div><div class="panel-body"><p class="description">支持 UTF-8 CSV（含表头）、JSON 数组、JSONL。每个分区独立上传；格式校验通过后才能运行。数据仅在当前浏览器内存中，点击计算才发送到所配置的训练服务。</p><div class="table-scroll feature-dictionary"><table><thead><tr><th>特征 / 字段</th><th>类型</th><th>要求</th><th>单位与说明</th></tr></thead><tbody>${m.features.map(f=>`<tr><td class="mono">${esc(f.name)}</td><td>${esc(f.type)}</td><td>${f.required?'必填':'可选'}${f.nullable?' · 可缺失':''}${f.target?' · 目标标签':''}</td><td>${esc([unitLabel(f.unit),f.description].filter(Boolean).join(' / ')||'标识或模型输入')}</td></tr>`).join('')}</tbody></table></div>${m.input_constraints?`<div class="studio-warning"><b>输入约束：</b>${esc(typeof m.input_constraints==='string'?m.input_constraints:JSON.stringify(m.input_constraints))}</div>`:''}<div class="studio-note"><b>划分建议：</b>${esc(m.split_policy)}。<br><b>评估指标：</b>${esc(m.metrics.join(' / '))}。精简神经网络为研究复现，需用现场数据验证。</div><details><summary>查看标准输入样例与推理请求</summary><pre class="studio-code">${esc(JSON.stringify(m.sample,null,2))}</pre><div class="compact-links">${button('下载CSV样例','sample-csv','small')}${button('下载JSONL样例','sample-jsonl','small')}${button('下载API请求样例','sample-api','small')}</div></details></div></section>
 ${renderModelTheory([m.id],{scope:'studio'})}
 <section class="panel section-gap"><div class="panel-head"><h2>02　上传整体数据与自动划分</h2>${button('一键载入演示数据','load-demo','small')}</div><div class="panel-body"><p class="description">完整数据可按自定比例划分；固定种子可复现。随机记录适用于独立样本；时序数据优先按日期，测井与文档数据优先按组。</p>${uploadSlot('overall',s,m)}<div class="split-controls"><label>训练 %<input data-studio-field="ratio0" type="number" min="1" max="98" value="${s.ratio[0]}"></label><label>验证 %<input data-studio-field="ratio1" type="number" min="1" max="98" value="${s.ratio[1]}"></label><label>测试 %<input data-studio-field="ratio2" type="number" min="1" max="98" value="${s.ratio[2]}"></label><label>划分策略<select data-studio-field="strategy"><option value="coverage" ${strategy==='coverage'?'selected':''}>三元组随机＋实体覆盖</option><option value="random" ${strategy==='random'?'selected':''}>固定种子随机记录</option><option value="group" ${strategy==='group'?'selected':''}>按组随机隔离</option><option value="time" ${strategy==='time'?'selected':''}>按日期先后</option></select></label><label>随机种子<input data-studio-field="seed" type="number" value="${s.seed}"></label><label>组字段<input data-studio-field="group" value="${esc(s.group??groupKey(m))}"></label><label>时间字段<input data-studio-field="date" value="${esc(s.date??'date')}"></label></div><div class="compact-links">${button('采用建议比例','recommend','small')}${button('划分整体数据','split','primary')}${button('下载划分清单','download-splits','small')}</div>${strategy==='random'&&['grin','anomaly_transformer','arps','crm','lag'].includes(m.id)?'<p class="studio-warning">时序数据随机记录划分可能泄漏未来信息。研究结果请使用按日期划分复核。</p>':''}${s.splitReport?`<p class="studio-note">${esc(s.splitReport)}</p>`:''}</div></section>
 <section class="panel section-gap"><div class="panel-head"><h2>03　独立分区数据接口</h2><span class="micro">已载入 ${total.toLocaleString()} 条</span></div><div class="panel-body"><div class="upload-grid">${['train','validation','test'].map(k=>uploadSlot(k,s,m)).join('')}</div>${overlap.identical?`<p class="studio-warning">跨分区发现 ${overlap.identical} 条相同记录，运行将阻断。请重新隔离数据。</p>`:''}${overlap.groups&&strategy==='group'?`<p class="studio-warning">${overlap.groups}个组跨分区，请按组重新划分。</p>`:''}<div class="studio-note">训练集用于拟合；验证集用于模型选择或阈值校准；测试集只用于最后评价。样例模板展示字段，完整演示数据可直接用于小规模训练。</div></div></section>
 <section class="panel section-gap"><div class="panel-head"><h2>04　模型计算与结果导出</h2>${button('清空本模型数据','clear','small')}</div><div class="panel-body">${uploadSlot('input',s,m)}<div class="service-config"><label>训练服务地址<input data-studio-setting="endpoint" type="url" value="${esc(endpoint)}" ${s.busy?'disabled':''} placeholder="http://127.0.0.1:8000 或 https://训练服务域名"></label><label>服务令牌（按需）<input data-studio-setting="token" type="password" value="${esc(token)}" ${s.busy?'disabled':''} autocomplete="off" placeholder="仅在当前会话内存中"></label>${button(connected?'重新检查连接':'检查连接','connect','small')}<span class="chip ${connected?'teal':'amber'}">${connected?'服务已连接':'未连接计算服务'}</span></div><p class="micro">GitHub Pages 提供网页；Python服务负责训练和计算。本机服务可同机启动后连接，远程服务需使用HTTPS并允许本站来源。每次运行基于当前训练分区重新拟合并用验证集选模，不复用上一次模型。未连接时不会生成虚构训练结果。</p><div class="run-controls"><label>训练轮数 / 上限<input data-studio-field="epochs" type="number" min="1" max="100" value="${s.epochs}"></label><label>批次 / 可复现种子<span class="mono">${s.seed}</span></label></div><div class="compact-links">${[['train',m.kind==='trainable'?'训练并评估':'拟合 / 机理校验'],['validate','验证模型'],['test','测试模型'],['predict','计算输入数据']].map(([op,t])=>`<button class="btn ${op==='train'?'primary':''}" data-studio-run="${op}" ${s.busy?'disabled':''}>${t}</button>`).join('')}${s.busy?button('取消请求','cancel','small'):''}</div>${s.busy?'<div class="studio-running"><span></span>计算服务实际执行中，请等待结果。<output id="studio-live-time">0.0 s</output></div>':''}${s.error?`<div class="studio-error" role="alert">${esc(s.error)}</div>`:''}${s.result?resultView(s):'<div class="studio-empty">运行成功后将在这里展示实际指标、计算结果与下载入口。</div>'}<details><summary>训练服务与数据说明</summary><p class="description">下载完整服务，在本机执行 README 的安装和启动步骤，再将地址填入上方。服务还提供 /docs 交互式API文档。历史实验未记录的训练时长显示“未记录”。运行期间结果不会自动写入GitHub。</p><div class="compact-links">${link('下载训练服务与源码','./downloads/chinaoil-training-platform.zip')}${link('数据模型用途对照','./downloads/model-data/original_zip_model_mapping.md')}${link('数据清单与校验','./downloads/model-data/manifest.json')}</div></details></div></section></div>
 <aside class="studio-side"><section class="panel"><div class="panel-head"><h2>模型结构</h2><span class="chip amber">${m.kind==='trainable'?'训练 / 推理':'机理 / 规则'}</span></div><div class="panel-body">${diagram(m)}<p class="micro">结构示意依据本项目实际实现。各节点与参数详见可下载服务源码。</p></div></section><section class="panel section-gap"><div class="panel-head"><h2>运行计时</h2></div><div class="panel-body"><div class="time-card"><span>${m.kind==='trainable'?'本次训练时长':'本次拟合 / 校准时长'}</span><strong>${s.result?(s.result.training_seconds===null?'无需训练':duration(s.result.training_seconds)):'—'}</strong></div><div class="time-card"><span>验证 / 测试 / 推理计算</span><strong>${s.result?duration(s.result.compute_seconds):'—'}</strong></div><div class="time-card"><span>请求总耗时</span><strong>${s.result?duration(s.elapsed):'—'}</strong></div><p class="micro">由实际执行计时返回；不同硬件、样本量及轮数会影响结果。历史训练时长：未记录。</p>${verificationView()}</div></section><section class="panel section-gap"><div class="panel-head"><h2>数据使用路径</h2></div><div class="panel-body"><ol class="studio-path"><li>查看字段、标签与格式</li><li>上传整体数据或三个分区</li><li>按模型建议隔离样本</li><li>连接独立计算服务</li><li>运行并下载结果与指标</li></ol><p class="micro">输入包含真实观测、可追溯转换及明确标注的生成算例。演示数据不能替代现场评估。</p></div></section></aside></div>`;
}
function uploadSlot(k,s,m){let r=s.slots[k],isInput=k==='input';return `<div class="upload-card ${r?'loaded':''}"><div class="flex between"><b>${labels[k]}</b><span class="micro">${r?`${r.length.toLocaleString()} 条`:'CSV / JSON / JSONL'}</span></div><p>${k==='train'?'拟合模型参数，仅使用此分区学习':k==='validation'?'选择参数、检查过拟合与阈值':k==='test'?'独立最终评价，不参与训练':k==='input'?'模型计算新样本；标注目标可省略':'整体数据校验后划分，覆盖已有三个分区'}</p><label class="upload-target">${r?'更换文件':'＋ 选择数据文件'}<input type="file" accept=".csv,.json,.jsonl,.ndjson" data-studio-upload="${k}" ${s.busy?'disabled':''}></label><span class="upload-filename">${esc(s.names[k]??'未选择文件')}</span><div class="compact-links">${button('格式与样例','sample-'+k,'small')}${r?button('下载已载入数据','export-'+k,'small'):''}</div>${r?`<details><summary>预览前4条</summary>${preview(r)}</details>`:''}</div>`}
function verificationView(){let v=verification.find(v=>v.model_id===selected);if(!v)return'';return `<details><summary>服务验证实测耗时 · 1 epoch</summary><div class="studio-note">这是交付前使用随附数据运行的CPU接口检查记录，${v.parameters?.epochs??1} epoch，IF树数${v.parameters?.trees??16}。不是当前上传数据的训练结果，也不代表正式训练耗时或现场精度。</div><div class="time-card"><span>实测训练 / 校准</span><strong>${v.training_seconds===null?'无需训练':duration(v.training_seconds)}</strong></div><div class="time-card"><span>实测计算</span><strong>${duration(v.compute_seconds)}</strong></div><a class="btn small" href="./assets/service-verification.json" download>下载实际接口验证记录</a></details>`}
function duration(v){return Number.isFinite(v)?v.toFixed(3)+' s':'未记录'}
function resultView(s){const r=s.result;let rows=Array.isArray(r.results)?r.results:Array.isArray(r.predictions)?r.predictions:null;return `<div class="studio-result"><div class="flex between"><h3>实际计算结果</h3><span class="chip teal">${esc(r.model_id??selected)} · ${esc(s.operation)}</span></div><div class="studio-metrics">${metrics(r.metrics).slice(0,30).join('')}</div>${(r.limitations?.length)?`<div class="studio-note">${r.limitations.map(esc).join('<br>')}</div>`:''}${r.warnings?.length?`<div class="studio-warning">${r.warnings.map(esc).join('<br>')}</div>`:''}${rows?preview(rows):`<pre class="studio-code">${esc(JSON.stringify(r.results??r.predictions??r,null,2).slice(0,6000))}</pre>`}<div class="compact-links">${button('下载完整结果 JSON','download-result','primary')}${button('下载计算结果 CSV','download-result-csv','small')}${button('下载运行与指标记录','download-report','small')}</div></div>`}
function invalidate(s){s.result=null;s.error='';s.elapsed=0;s.splitReport=null;}
function checkSlot(rows,m,inference=false){let v=validateRows(rows,m,{inference});if(!v.valid)throw Error(v.errors.join('；')+(v.totalErrors>12?`，共${v.totalErrors}项错误`:''));return v.rows;}
function assertNotBusy(){if(cur().busy)throw Error('计算运行中，请先等待或取消请求');}
async function action(a){let s=cur(),m=spec();try{if(a==='cancel'){controller?.abort();return}if(a==='download-result')return download(s.result,selected+'-result.json');if(a==='download-report')return download({model_id:selected,operation:s.operation,input_counts:Object.fromEntries(Object.entries(s.slots).map(([k,v])=>[k,v.length])),split:{ratios:s.ratio,strategy:s.strategy??policy(m),seed:s.seed},metrics:s.result?.metrics,training_seconds:s.result?.training_seconds,compute_seconds:s.result?.compute_seconds,request_seconds:s.elapsed},selected+'-run-report.json');if(a==='download-result-csv'){let rows=s.result.results??s.result.predictions??[s.result];return download(csv(Array.isArray(rows)?rows:[rows]),selected+'-results.csv')}
 if(a==='connect'){let url=serviceURL();let r=await fetch(url+'/health',{headers:headers(),credentials:'omit',redirect:'error',signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('服务连接失败 HTTP '+r.status);let data=await r.json();if(data.status!=='ok')throw Error('服务健康检查返回异常');connected=true;s.error='';notice('计算服务连接成功');rerender();return;}
 if(a.startsWith('sample-')){let what=a.slice(7);if(what==='api')return download({model_id:selected,operation:'train',train:m.sample,validation:[],test:[],input:[],parameters:{epochs:s.epochs,seed:s.seed},note:'此为字段模板；训练前请替换成足量独立分区数据'},selected+'-request-template.json');if(what==='csv')return download(csv(m.sample),selected+'-format-example.csv');if(what==='jsonl')return download(m.sample.map(x=>JSON.stringify(x)).join('\n'),selected+'-format-example.jsonl');download({model_id:selected,partition:what,format:'CSV / JSON / JSONL',features:m.features,records:m.sample,note:'格式样例不是完整训练数据。验证、测试和训练应来自独立样本；计算输入可不含标签。'},selected+'-'+what+'-input-example.json');return;}
 if(a.startsWith('export-'))return download(s.slots[a.slice(7)],selected+'-'+a.slice(7)+'.json');if(a==='download-splits')return download({model_id:selected,seed:s.seed,ratios:s.ratio,strategy:s.strategy??policy(m),partitions:s.slots},selected+'-dataset-splits.json');assertNotBusy();
 if(a==='clear'){cache[selected]=fresh();rerender();return}if(a==='recommend'){s.ratio=[...(m.recommended_split??[70,15,15])];s.strategy=policy(m);rerender();return}
 if(a==='split'){if(!s.slots.overall)throw Error('请先上传整体数据');let parts=splitData(s.slots.overall,s.ratio,s.strategy??policy(m),s.seed,s.group??groupKey(m),s.date??'date');invalidate(s);Object.assign(s.slots,parts);for(let k of Object.keys(parts))s.names[k]='由整体数据划分';s.splitReport=`实际记录数：训练 ${parts.train.length} / 验证 ${parts.validation.length} / 测试 ${parts.test.length}；分组或日期边界保持完整，实际比例以记录数为准。种子 ${s.seed}。`;rerender();return}
 if(a==='load-demo'){let id=selected;s.busy=true;s.error='';rerender();let parts=await Promise.all(['train','validation','test','input'].map(async k=>{let r=await fetch(`./downloads/model-data/${id}/${k==='input'?'infer':k}.jsonl`);if(!r.ok)throw Error('演示数据不可用 HTTP '+r.status);return[k,checkSlot(parseData(await r.text(),'jsonl'),m,k==='input')]}));invalidate(s);for(let[k,v]of parts){s.slots[k]=v;s.names[k]='已标注来源的演示数据 · '+k}s.slots.overall=['train','validation','test'].flatMap(k=>s.slots[k]);s.names.overall='三个演示分区合并';s.busy=false;notice('已加载完整演示分区，来源见数据包说明');rerender();return;}
 }catch(e){s.error=e.message;if(a==='connect')connected=false;s.busy=false;rerender();}}
function serviceURL(){let u;try{u=new URL(endpoint)}catch{throw Error('请填写训练服务完整地址，例如 http://127.0.0.1:8000')};if(!['http:','https:'].includes(u.protocol)||u.username||u.password||u.search||u.hash)throw Error('训练服务地址必须为不含账号密码、查询参数的HTTP(S)地址');return u.href.replace(/\/$/,'')}
function headers(){return{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})}}
async function run(op){let s=cur(),m=spec();try{assertNotBusy();let url=serviceURL();if(!s.slots.train?.length)throw Error('请上传训练数据：模型仅以训练分区拟合参数');if(op!=='predict'&&(!s.slots.validation?.length||!s.slots.test?.length))throw Error('请分别上传训练、验证、测试数据');if(op==='predict'&&!s.slots.input?.length)throw Error('请上传用于模型计算的新输入数据');let overlap=overlapReport(s.slots,s.group??groupKey(m));if(overlap.identical)throw Error('训练、验证、测试之间存在相同记录，请先消除重复');if((s.strategy??policy(m))==='group'&&overlap.groups)throw Error('按组隔离模式检测到跨分区同组，请重新划分或调整策略');s.result=null;s.error='';s.busy=true;s.started=performance.now();s.operation=op;controller=new AbortController();let body={model_id:selected,operation:op,train:s.slots.train??[],validation:s.slots.validation??[],test:s.slots.test??[],input:s.slots.input??[],parameters:{epochs:s.epochs,seed:s.seed}};rerender();let timer=setInterval(()=>{let el=document.querySelector('#studio-live-time');if(el)el.textContent=((performance.now()-s.started)/1000).toFixed(1)+' s'},200);try{let r=await fetch(url+'/api/run',{method:'POST',headers:headers(),credentials:'omit',redirect:'error',body:JSON.stringify(body),signal:controller.signal});let result=await r.json();if(!r.ok)throw Error(typeof result.detail==='string'?result.detail:JSON.stringify(result.detail??result));s.elapsed=(performance.now()-s.started)/1000;s.result=result;connected=true;notice('计算完成，结果与实际耗时已返回');}finally{clearInterval(timer);s.busy=false;controller=null}rerender();}catch(e){s.busy=false;s.error=e.name==='AbortError'?'请求已取消。服务端任务可能仍在完成当前计算。':e.message.startsWith('Failed to fetch')?'无法连接训练服务。请确认服务已启动、地址正确，并允许本站跨域请求。':e.message;rerender();}}
export function setupStudio({models,refresh,notify,verificationData}){verification=verificationData?.runs??[];contracts=models;rerender=refresh;notice=notify;document.addEventListener('input',e=>{let el=e.target,s=cur();if(s.busy)return;if(el.dataset.studioSetting){if(el.dataset.studioSetting==='endpoint')endpoint=el.value.trim();else token=el.value;connected=false;}if(el.dataset.studioField){let k=el.dataset.studioField;invalidate(s);if(k.startsWith('ratio'))s.ratio[+k.at(-1)]=Number(el.value);else if(k!=='strategy')s[k]=['seed','epochs'].includes(k)?Number(el.value):el.value;}});document.addEventListener('click',e=>{let el=e.target.closest('[data-studio],[data-studio-model],[data-studio-run]');if(!el)return;e.preventDefault();if(el.dataset.studioModel){if(cur().busy){notice('请先等待当前计算完成或取消');return}selected=el.dataset.studioModel;rerender()}else if(el.dataset.studioRun)run(el.dataset.studioRun);else action(el.dataset.studio)});document.addEventListener('change',async e=>{let el=e.target,s=cur();if(el.dataset.studioSetting){if(s.busy)return;let k=el.dataset.studioSetting;if(k==='endpoint')endpoint=el.value.trim();else token=el.value;connected=false;s.error='';return}if(el.dataset.studioField){if(s.busy)return;let k=el.dataset.studioField;invalidate(s);if(k.startsWith('ratio'))s.ratio[+k.at(-1)]=Number(el.value);else s[k]=['seed','epochs'].includes(k)?Number(el.value):el.value;if(k==='strategy')rerender();return}if(el.dataset.studioUpload){try{assertNotBusy();let file=el.files[0];if(!file)return;if(file.size>30*1024*1024)throw Error('单个文件上限30MB，请先抽样或分批处理');let slot=el.dataset.studioUpload;let rows=checkSlot(parseData(await file.text(),file.name.split('.').at(-1).toLowerCase()),spec(),slot==='input');invalidate(s);s.slots[slot]=rows;s.names[slot]=file.name;rerender();notice(labels[slot]+'已校验并加载')}catch(e){s.error=e.message;rerender()}}});}
